import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
import base64
from io import BytesIO
import json
import re

# Set plotting style
plt.style.use('default')
sns.set_theme(style="whitegrid")

def clean_data(df):
    # Clean prices
    def clean_currency(x):
        if pd.isna(x): return np.nan
        x = str(x).replace('₹', '').replace(',', '')
        try:
            return float(x)
        except:
            return np.nan

    df['discounted_price'] = df['discounted_price'].apply(clean_currency)
    df['actual_price'] = df['actual_price'].apply(clean_currency)

    # Clean discount percentage
    def clean_pct(x):
        if pd.isna(x): return np.nan
        x = str(x).replace('%', '')
        try:
            return float(x)
        except:
            return np.nan

    df['discount_percentage'] = df['discount_percentage'].apply(clean_pct)

    # Clean rating count
    def clean_count(x):
        if pd.isna(x): return np.nan
        x = str(x).replace(',', '')
        try:
            return int(x)
        except:
            return np.nan

    df['rating_count'] = df['rating_count'].apply(clean_count)

    # Clean rating (one value is '\|' in Kaggle dataset)
    def clean_rating(x):
        if pd.isna(x): return np.nan
        try:
            return float(x)
        except:
            return np.nan

    df['rating'] = df['rating'].apply(clean_rating)

    # Extract top-level category
    def extract_main_category(x):
        if pd.isna(x): return 'Unknown'
        return str(x).split('|')[0]

    def extract_sub_category(x):
        if pd.isna(x): return 'Unknown'
        parts = str(x).split('|')
        return parts[1] if len(parts) > 1 else 'Unknown'

    df['main_category'] = df['category'].apply(extract_main_category)
    df['sub_category'] = df['category'].apply(extract_sub_category)

    return df

def get_base64_plot(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', dpi=120)
    buf.seek(0)
    img_str = base64.b64encode(buf.read()).decode('utf-8')
    plt.close(fig)
    return img_str

def main():
    print("Reading data...")
    df = pd.read_csv('/app/benchmark/data.csv')
    df = clean_data(df)

    print("Calculating metrics...")
    total_products = len(df)
    avg_rating = df['rating'].mean()
    avg_discount = df['discount_percentage'].mean()
    median_rating_count = df['rating_count'].median()
    high_rating_share = (df['rating'] >= 4.0).sum() / df['rating'].notna().sum()
    correlation_discount_rating = df['discount_percentage'].corr(df['rating'])

    # 1. Category Performance Breakdown
    print("Plotting Category...")
    cat_summary = df.groupby('main_category').agg({
        'rating': 'mean',
        'rating_count': 'sum',
        'discount_percentage': 'mean',
        'product_id': 'count'
    }).rename(columns={'product_id': 'product_count'}).reset_index()

    # Filter top categories by product count for clearer charts
    top_cats = cat_summary[cat_summary['product_count'] >= 10].sort_values('rating', ascending=False)

    fig, ax = plt.subplots(figsize=(10, 6))
    sns.barplot(data=top_cats, x='rating', y='main_category', palette='viridis', ax=ax)
    ax.set_title('Average Rating by Main Category', fontsize=14)
    ax.set_xlabel('Average Rating')
    ax.set_ylabel('')
    ax.set_xlim(3.5, 4.5)
    img_cat_rating = get_base64_plot(fig)

    fig, ax = plt.subplots(figsize=(10, 6))
    sns.scatterplot(data=top_cats, x='discount_percentage', y='rating', size='product_count', sizes=(50, 500), alpha=0.7, ax=ax)
    for i, row in top_cats.iterrows():
        ax.text(row['discount_percentage']+1, row['rating'], row['main_category'], fontsize=9)
    ax.set_title('Category Level: Discount % vs Rating', fontsize=14)
    ax.set_xlabel('Average Discount %')
    ax.set_ylabel('Average Rating')
    img_cat_scatter = get_base64_plot(fig)

    # 2. Pricing & Discount Strategy Analysis
    print("Plotting Pricing...")
    fig, ax = plt.subplots(figsize=(10, 6))
    sns.histplot(data=df, x='discount_percentage', bins=20, kde=True, color='teal', ax=ax)
    ax.set_title('Distribution of Discount Percentages', fontsize=14)
    ax.set_xlabel('Discount %')
    ax.set_ylabel('Count of Products')
    img_discount_dist = get_base64_plot(fig)

    fig, ax = plt.subplots(figsize=(10, 6))
    sns.regplot(data=df.dropna(subset=['discount_percentage', 'rating']), x='discount_percentage', y='rating', 
                scatter_kws={'alpha':0.2, 'color':'indigo'}, line_kws={'color':'red'}, ax=ax)
    ax.set_title(f'Discount % vs Customer Rating (Correlation: {correlation_discount_rating:.3f})', fontsize=14)
    ax.set_xlabel('Discount %')
    ax.set_ylabel('Rating')
    img_discount_rating = get_base64_plot(fig)

    # 3. Customer Engagement & Rating Distribution
    print("Plotting Engagement...")
    fig, ax = plt.subplots(figsize=(10, 6))
    sns.histplot(data=df, x='rating', bins=20, color='coral', ax=ax)
    ax.set_title('Distribution of Product Ratings', fontsize=14)
    ax.set_xlabel('Rating')
    ax.set_ylabel('Count of Products')
    img_rating_dist = get_base64_plot(fig)

    fig, ax = plt.subplots(figsize=(10, 6))
    # log scale for rating count
    sns.scatterplot(data=df, x='rating_count', y='rating', alpha=0.3, color='dodgerblue', ax=ax)
    ax.set_xscale('log')
    ax.set_title('Rating vs Engagement (Review Count - Log Scale)', fontsize=14)
    ax.set_xlabel('Total Ratings (Log Scale)')
    ax.set_ylabel('Average Rating')
    img_rating_engagement = get_base64_plot(fig)

    # 4. Sentiment (simple top words extraction from titles if possible)
    # We will just do a placeholder qualitative text since we are generating an HTML report without complex NLP
    # We can extract a few raw examples of top/bottom rated.
    top_products = df.nlargest(5, 'rating')[['product_name', 'rating', 'main_category']].to_html(index=False, classes='data-table')
    bottom_products = df.nsmallest(5, 'rating')[['product_name', 'rating', 'main_category']].to_html(index=False, classes='data-table')

    html = f'''
    <!DOCTYPE html>
    <html lang="en">
    <head>
        <meta charset="UTF-8">
        <meta name="viewport" content="width=device-width, initial-scale=1.0">
        <title>Amazon Product Catalog Performance & Customer Sentiment Analysis</title>
        <style>
            :root {{
                --primary: #232F3E;
                --secondary: #FF9900;
                --bg: #F3F3F3;
                --text: #0F1111;
                --card-bg: #FFFFFF;
                --border: #DDDDDD;
                --success: #007600;
                --danger: #B12704;
            }}
            body {{
                font-family: 'Amazon Ember', Arial, sans-serif;
                margin: 0;
                padding: 0;
                background-color: var(--bg);
                color: var(--text);
                line-height: 1.6;
            }}
            header {{
                background-color: var(--primary);
                color: white;
                padding: 40px 20px;
                text-align: center;
            }}
            header h1 {{
                margin: 0;
                font-size: 2.5em;
                color: var(--secondary);
            }}
            header p {{
                margin-top: 10px;
                font-size: 1.2em;
                opacity: 0.9;
            }}
            .container {{
                max-width: 1200px;
                margin: 0 auto;
                padding: 20px;
            }}
            .section {{
                background: var(--card-bg);
                border-radius: 8px;
                padding: 30px;
                margin-bottom: 30px;
                box-shadow: 0 2px 5px rgba(0,0,0,0.05);
                border: 1px solid var(--border);
            }}
            .section h2 {{
                color: var(--primary);
                border-bottom: 2px solid var(--secondary);
                padding-bottom: 10px;
                margin-top: 0;
            }}
            .kpi-grid {{
                display: grid;
                grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
                gap: 20px;
                margin-bottom: 30px;
            }}
            .kpi-card {{
                background: var(--bg);
                padding: 20px;
                border-radius: 6px;
                text-align: center;
                border-left: 4px solid var(--secondary);
            }}
