                font-size: 2em;
                font-weight: bold;
                color: var(--primary);
                margin: 10px 0;
            }}
            .kpi-label {{
                font-size: 0.9em;
                color: #555;
                text-transform: uppercase;
                letter-spacing: 0.5px;
            }}
            .kpi-desc {{
                font-size: 0.8em;
                color: #777;
                margin-top: 5px;
            }}
            .chart-row {{
                display: flex;
                flex-wrap: wrap;
                gap: 20px;
                margin-bottom: 20px;
            }}
            .chart-container {{
                flex: 1;
                min-width: 400px;
                background: white;
                text-align: center;
            }}
