    os.makedirs('/app/output', exist_ok=True)
    with open('/app/output/final_report.html', 'w', encoding='utf-8') as f:
        f.write(html)
    print("Report generated successfully at /app/output/final_report.html")

if __name__ == "__main__":
    main()
